const express = require('express');
const app = express();

app.use(express.json());

function evalRule(req) {
  const expr = req.body.rule;
  const ctx = { ctx: req.body.context, req };
  return Function('ctx', 'req', `return (${expr});`)(ctx.ctx, req);
}

app.post('/check', (req, res) => {
  try {
    if (!req.body || typeof req.body !== 'object') {
      return res.status(400).json({ error: 'Request body must be a JSON object' });
    }

    if (!req.body.rule || typeof req.body.rule !== 'string') {
      return res.status(400).json({ error: 'Missing or invalid "rule" field (must be a string)' });
    }

    if (!req.body.context || typeof req.body.context !== 'object') {
      return res.status(400).json({ error: 'Missing or invalid "context" field (must be an object)' });
    }

    const result = evalRule(req);

    res.json({
      result: result,
      evaluated: true,
      rule: req.body.rule,
      context: req.body.context
    });

  } catch (error) {
    res.status(400).json({
      error: 'Rule evaluation failed',
      message: error.message,
      rule: req.body?.rule,
      context: req.body?.context
    });
  }
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

const fs = require('fs');

// Read .env.test file
const envContent = fs.readFileSync('.env.test', 'utf8');

// Parse environment variables (skip comments and empty lines)
const envVars = {};
const lines = envContent.split('\n');

lines.forEach(line => {
  line = line.trim();
  // Skip comments and empty lines
  if (line.startsWith('#') || line === '') return;

  // Parse KEY=VALUE
  const match = line.match(/^([^=]+)=(.*)$/);
  if (match) {
    const key = match[1].trim();
    const value = match[2].trim();
    envVars[key] = value;
  }
});

// Convert to JSON
const jsonData = JSON.stringify(envVars, null, 2);
console.log(jsonData);

// Write to temp file for cURL
fs.writeFileSync('/tmp/env_vars.json', jsonData);

