// Secure application with environment-based configuration
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');

// Validate required environment variables in production
const requiredEnvVars = ['NODE_ENV'];
if (process.env.NODE_ENV === 'production') {
  requiredEnvVars.push('JWT_SECRET');
}

const missingEnvVars = requiredEnvVars.filter(envVar => !process.env[envVar]);
if (missingEnvVars.length > 0) {
  throw new Error(`Missing required environment variables: ${missingEnvVars.join(', ')}`);
}

const app = express();

// Apply security headers from environment
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: process.env.CSP_DEFAULT_SRC?.split(' ') || ["'self'"],
      scriptSrc: process.env.CSP_SCRIPT_SRC?.split(' ') || ["'self'", "'unsafe-inline'"],
      styleSrc: process.env.CSP_STYLE_SRC?.split(' ') || ["'self'", "'unsafe-inline'"],
      imgSrc: process.env.CSP_IMG_SRC?.split(' ') || ["'self'", "data:"],
    },
  },
  hsts: {
    maxAge: parseInt(process.env.HSTS_MAX_AGE) || 31536000,
    includeSubDomains: process.env.HSTS_INCLUDE_SUBDOMAINS !== 'false',
    preload: process.env.HSTS_PRELOAD !== 'false',
  },
  // Only enable HSTS in production
  ...(process.env.NODE_ENV !== 'production' && { hsts: false }),
}));

// Rate limiting from environment
const limiter = rateLimit({
  windowMs: parseInt(process.env.RATE_LIMIT_WINDOW_MS) || 15 * 60 * 1000,
  max: parseInt(process.env.RATE_LIMIT_MAX_REQUESTS) || 100,
  message: process.env.RATE_LIMIT_MESSAGE || 'Too many requests from this IP, please try again later.',
  standardHeaders: process.env.RATE_LIMIT_STANDARD_HEADERS !== 'false',
  legacyHeaders: process.env.RATE_LIMIT_LEGACY_HEADERS !== 'false',
});
app.use(limiter);

// API-specific rate limit from environment
const apiLimiter = rateLimit({
  windowMs: parseInt(process.env.API_RATE_LIMIT_WINDOW_MS) || 15 * 60 * 1000,
  max: parseInt(process.env.API_RATE_LIMIT_MAX_REQUESTS) || 20,
  message: process.env.API_RATE_LIMIT_MESSAGE || 'Too many API requests from this IP, please try again later.',
  standardHeaders: process.env.RATE_LIMIT_STANDARD_HEADERS !== 'false',
  legacyHeaders: process.env.RATE_LIMIT_LEGACY_HEADERS !== 'false',
});

// Input validation with configurable limits
const validateInput = (req, res, next) => {
  const maxInputLength = parseInt(process.env.MAX_INPUT_LENGTH) || 200;

  if (req.query && typeof req.query === 'object') {
    for (const key in req.query) {
      const value = req.query[key];
      // Check length
      if (typeof value === 'string' && value.length > maxInputLength) {
        return res.status(400).json({ error: 'Input too long' });
      }
      // Basic XSS pattern detection - could be environment-configurable
      if (typeof value === 'string' && /<script|javascript:|on\w+\s*=|"/i.test(value)) {
        return res.status(400).json({ error: 'Invalid input detected' });
      }
    }
  }
  next();
};

app.use(validateInput);

// Health endpoint
app.get('/health', (req, res) => {
  res.status(200).json({ status: 'ok' });
});

// Users endpoint with authentication
app.get('/users', apiLimiter, (req, res) => {
  const authHeader = req.headers.authorization;
  const bearerPrefix = process.env.BEARER_TOKEN_PREFIX || 'Bearer';
  const prefix = bearerPrefix + ' ';

  if (!authHeader || !authHeader.startsWith(prefix)) {
    return res.status(401).json({ error: 'Unauthorized' });
  }

  // Extract and validate token
  const token = authHeader.slice(prefix.length);
  if (!token || token.length === 0) {
    return res.status(401).json({ error: 'Invalid token' });
  }

  // In production, verify JWT properly using JWT_SECRET
  // Example: jwt.verify(token, process.env.JWT_SECRET)

  // Strip sensitive environment variables for production responses
  const shouldStrip = process.env.NODE_ENV === 'production' || process.env.STRIP_PII === 'true';

  const users = [
    { 
      id: 1, 
      name: 'Alice', 
      ...(shouldStrip ? { email: '***@***.***' } : { email: 'alice@example.com' }) 
    },
    { 
      id: 2, 
      name: 'Bob', 
      ...(shouldStrip ? { email: '***@***.***' } : { email: 'bob@example.com' }) 
    },
  ];

  res.json(users);
});

// Catch-all for undefined routes
app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});

// Error handling middleware
app.use((err, req, res, next) => {
  // Log without exposing sensitive information
  const logLevel = process.env.LOG_LEVEL || 'info';

  if (logLevel === 'debug' || logLevel === 'error') {
    console.error(`[${new Date().toISOString()}] Error: ${err.message}`);
  } else if (logLevel === 'info') {
    console.error(`[${new Date().toISOString()}] Error occurred`);
  }

  const status = err.status || 500;
  const isProduction = process.env.NODE_ENV === 'production';
  const exposeErrors = process.env.EXPOSE_ERRORS === 'true';

  res.status(status).json({
    error: (!isProduction || exposeErrors) ? err.message : 'Internal server error',
    ...(process.env.INCLUDE_ERROR_STACK === 'true' && { stack: err.stack }),
  });
});

// Server configuration from environment
const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '0.0.0.0';

const server = app.listen(PORT, HOST, () => {
  console.log(`[${new Date().toISOString()}] Server running on ${HOST}:${PORT}`);
  console.log(`[${new Date().toISOString()}] Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown handling
const shutdown = (signal) => {
  console.log(`[${new Date().toISOString()}] ${signal} received, shutting down gracefully...`);
  server.close(() => {
    console.log(`[${new Date().toISOString()}] Server closed`);
    process.exit(0);
  });

  // Force shutdown after timeout
  setTimeout(() => {
    console.error(`[${new Date().toISOString()}] Forced shutdown after timeout`);
    process.exit(1);
  }, parseInt(process.env.SHUTDOWN_TIMEOUT) || 10000);
};

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT', () => shutdown('SIGINT'));

module.exports = app;

